// Positive decimal multiplication rounded half-up to integer sen, matching backend Decimal.
function myrRoundProduct(a,b,divisor=1){
 a=Number(a)||0;b=Number(b)||0;
 if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||b<0)return Math.round(a*b/divisor);
 const parts=n=>{const [base,exp='0']=String(n).toLowerCase().split('e');const [whole,fraction='']=base.split('.');return [BigInt(whole+fraction),fraction.length-Number(exp)]};
 const [x,xs]=parts(a),[y,ys]=parts(b);const scale=xs+ys;
 let numerator=x*y,denominator=BigInt(divisor);
 if(scale>=0)denominator*=10n**BigInt(scale);else numerator*=10n**BigInt(-scale);
 return Number((2n*numerator+denominator)/(2n*denominator));
}
